import SwiftUI
import ShopdeckCore
struct AutomationReviewSection:View {
    var model:AppModel
    @LocalState<AutomationOperation?> private var reviewing:AutomationOperation?
    @LocalState<Bool> private var busy=false
    var operations:[AutomationOperation]{model.automationQueue.operations.filter{model.selectedShopID==nil || $0.shopID==model.selectedShopID}.reversed()}
    var body:some View {
        ForEach(operations){operation in Panel{VStack(alignment:.leading,spacing:14){HStack{Image(systemName:icon(operation.kind)).foregroundStyle(Theme.blue);Text(operation.title).font(.headline);Spacer();StatusPill(text:T(operation.status),color:operation.status=="applied" ? .green:.orange)};Text(operation.shopName+" · "+operation.reason).font(.callout).foregroundStyle(.secondary);AutomationPlanView(operation:operation,store:model.store);if let error=operation.error{Text(error).font(.caption).foregroundStyle(.orange)};if let result=operation.result{DisclosureGroup(T("Ergebnis und Nachweis")){Text(result.pretty).font(.system(size:11,design:.monospaced)).textSelection(.enabled)}};if operation.status=="pending"{HStack{Button(T("Ablehnen")){Task{await model.resolveOperation(operation,apply:false)}};Spacer();Button(T("Prüfen und übernehmen")){reviewing=operation}.buttonStyle(.borderedProminent)}}}}}
        .sheet(item:$reviewing){operation in VStack(alignment:.leading,spacing:20){Text(operation.title).font(.title2.bold());Text(operation.shopName).font(.headline);ScrollView{AutomationPlanView(operation:operation,store:model.store)};if operation.kind=="plugin"{Text(T("Das Plugin führt nach Installation Code im Shop aus. Shopware prüft Abhängigkeiten bei der Installation.")).font(.callout).foregroundStyle(.orange)};Text(T("Die Dateien und Aktionen werden gemeinsam freigegeben. Jeder Schritt wird protokolliert. Bei einem Fehler bleiben Teilstände sichtbar.")).font(.caption).foregroundStyle(.secondary);HStack{Button(T("Abbrechen")){reviewing=nil}.disabled(busy);Spacer();Button(T("Jetzt ausführen")){Task{busy=true;await model.resolveOperation(operation,apply:true);busy=false;reviewing=nil}}.buttonStyle(.borderedProminent).disabled(busy)}}.padding(28).frame(width:760,height:680).interactiveDismissDisabled(busy)}
    }
    private func icon(_ kind:String)->String{kind=="campaign" ? "rectangle.3.group":kind=="plugin" ? "puzzlepiece.extension":kind=="media" ? "photo":"sparkles"}
}
struct AutomationPlanView:View {
    let operation:AutomationOperation
    let store:WorkspaceStore
    var body:some View{VStack(alignment:.leading,spacing:12){
        ForEach(operation.files){file in HStack(spacing:14){if file.mimeType.hasPrefix("image/"),let image=NSImage(contentsOf:store.stagedPreviewURL(file)){Image(nsImage:image).resizable().scaledToFit().frame(width:140,height:90).clipShape(RoundedRectangle(cornerRadius:8))}else{Image(systemName:"puzzlepiece.extension").font(.largeTitle).foregroundStyle(Theme.blue).frame(width:60)};VStack(alignment:.leading,spacing:4){Text(file.name+"."+file.fileExtension).fontWeight(.medium);Text(ByteCountFormatter.string(fromByteCount:Int64(file.byteCount),countStyle:.file)).font(.caption).foregroundStyle(.secondary);if file.mimeType=="application/zip"{Text((file.metadata["technicalName"].string ?? "")+" "+(file.metadata["version"].string ?? "")).font(.caption);Text("Shopware "+(file.metadata["coreConstraint"].string ?? "")).font(.caption)}}}}
        if operation.kind=="campaign"{Text((operation.payload["sales_channel_name"].string ?? "")+" · "+operation.shopName).font(.caption).foregroundStyle(.secondary);Label(operation.payload["publish"].bool==true ? T("Nach Freigabe veröffentlichen"):T("Als Entwurf speichern"),systemImage:operation.payload["publish"].bool==true ? "globe":"doc").foregroundStyle(operation.payload["publish"].bool==true ? Color.orange:Theme.blue);ForEach(Array(operation.payload["sections"].array.enumerated()),id:\.offset){index,section in HStack(alignment:.top){Text(String(index+1)).font(.caption.monospacedDigit()).foregroundStyle(.secondary).frame(width:20);VStack(alignment:.leading,spacing:5){Text(section["type"].string ?? "").font(.caption.bold()).foregroundStyle(Theme.blue);if let text=section["text"].string{Text(text).font(.callout).textSelection(.enabled)};if section["type"].string=="image",let index=section["file_index"].number,operation.files.indices.contains(Int(index)),let image=NSImage(contentsOf:store.stagedPreviewURL(operation.files[Int(index)])){Image(nsImage:image).resizable().scaledToFit().frame(maxWidth:420,maxHeight:190).clipShape(RoundedRectangle(cornerRadius:8))};if section["type"].string=="product_slider"{Text("\(section["product_ids"].array.count) "+T("Produkte")).font(.callout);ForEach(operation.payload["product_previews"].array.filter{section["product_ids"].array.contains($0["id"])},id:\.pretty){product in Text((product["name"].string ?? "")+" · "+(product["productNumber"].string ?? "")).font(.caption).foregroundStyle(.secondary)}}}}.padding(12).frame(maxWidth:.infinity,alignment:.leading).background(Theme.blue.opacity(0.05),in:RoundedRectangle(cornerRadius:8))}}
        if operation.kind=="plugin"{Label(operation.payload["activate"].bool==true ? T("Installieren und aktivieren"):T("Nur installieren"),systemImage:"checkmark.shield").font(.callout)}
        DisclosureGroup(T("Technischen Plan anzeigen")){Text(operation.payload.pretty).font(.system(size:11,design:.monospaced)).textSelection(.enabled)}
    }}
}
